   // note, in Pascal for-loop-limits are inclusive
   for i := 1 to n do
   begin
      f[next] := f[previous] + f[current];
      f[previous] := f[current];
      f[current] := f[next];
   end;

   // assign to previous, bc f[current] = f[next] for next iteration
   fibonacci := f[previous];
end;

